package com.smritisathi.app.voice;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.speech.*;import android.speech.tts.TextToSpeech;import android.widget.*;import java.util.*;import com.smritisathi.app.core.*;import com.smritisathi.app.reminders.ReminderActivity;import com.smritisathi.app.games.MemoryMatchActivity;
public class TalkToSathiActivity extends BaseActivity {TextView status;SpeechRecognizer sr;TextToSpeech tts;@Override public void onCreate(Bundle b){super.onCreate(b);header("Talk to Sathi");status=UI.card(this,"Tap the microphone and ask me anything!");root.addView(status);Button mic=UI.button(this,"🎙 Start Listening");root.addView(mic);tts=new TextToSpeech(this,s->{if(s==TextToSpeech.SUCCESS)tts.setLanguage(Locale.ENGLISH);});mic.setOnClickListener(v->listen());}void listen(){if(Build.VERSION.SDK_INT>=23&&checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},42);return;}status.setText("Listening...");sr=SpeechRecognizer.createSpeechRecognizer(this);sr.setRecognitionListener(new RecognitionListener(){public void onReadyForSpeech(Bundle b){}public void onBeginningOfSpeech(){}public void onRmsChanged(float r){}public void onBufferReceived(byte[] b){}public void onEndOfSpeech(){}public void onError(int e){respond("I didn't quite catch that, please try again.");}public void onResults(Bundle b){ArrayList<String> a=b.getStringArrayList(SpeechRecognizer.RESULTS_RECOGNITION);String x=a==null||a.isEmpty()?"":a.get(0);String intent=VoiceIntents.match(x);if(intent.equals("reminders")){respond("Let me check your schedule for today.");startActivity(new Intent(TalkToSathiActivity.this,ReminderActivity.class));}else if(intent.equals("medicine")){respond("Let me check when your next medicine is scheduled.");startActivity(new Intent(TalkToSathiActivity.this,ReminderActivity.class));}else if(intent.equals("game")){respond("Opening your memory exercise now. Let's play!");startActivity(new Intent(TalkToSathiActivity.this,MemoryMatchActivity.class));}else respond("I didn't quite catch that, please try again.");}public void onPartialResults(Bundle b){}public void onEvent(int a,Bundle b){}});Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,Locale.getDefault());sr.startListening(i);}void respond(String s){status.setText(s);if(tts!=null)tts.speak(s,TextToSpeech.QUEUE_FLUSH,null,"sathi");}@Override protected void onDestroy(){if(sr!=null)sr.destroy();if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}}
